export default function setAcceptedSolutions(topic, acceptedAnswers) {
  const acceptedPostNumbers = new Set(
    acceptedAnswers?.map((answer) => answer.post_number)
  );

  const topicHasAcceptedAnswer = acceptedPostNumbers.size > 0;

  topic.accepted_answers = acceptedAnswers;
  topic.has_accepted_answer = topicHasAcceptedAnswer;

  const posts = new Set(topic.postStream?.posts);
  topic.postStream?.loadedPosts?.forEach((post) => posts.add(post));

  posts.forEach((post) => {
    if (post.post_number === 1) {
      return;
    }

    post.setProperties({
      accepted_answer: acceptedPostNumbers.has(post.post_number),
      topic_accepted_answer: topicHasAcceptedAnswer,
    });
  });
}
import Component from "@glimmer/component";
import { tracked } from "@glimmer/tracking";
import { action } from "@ember/object";
import { service } from "@ember/service";
import { ajax } from "discourse/lib/ajax";
import { popupAjaxError } from "discourse/lib/ajax-error";
import DButton from "discourse/ui-kit/d-button";
import setAcceptedSolutions from "../lib/set-accepted-solutions.js";

export default class SolvedAcceptAnswerButton extends Component {
  static hidden(args, context) {
    if (context.siteSettings.solved_allow_multiple_solutions) {
      return false;
    }
    return args.post.topic_accepted_answer;
  }

  @service appEvents;
  @service currentUser;

  @tracked saving = false;

  get showLabel() {
    return this.currentUser?.id === this.args.post.topicCreatedById;
  }

  @action
  async acceptAnswer() {
    const post = this.args.post;

    this.saving = true;
    try {
      await acceptPost(post, this.currentUser);

      this.appEvents.trigger("discourse-solved:solution-toggled", post);
    } catch (e) {
      popupAjaxError(e);
    } finally {
      this.saving = false;
    }
  }

  <template>
    <DButton
      class="post-action-menu__solved-unaccepted unaccepted"
      ...attributes
      @action={{this.acceptAnswer}}
      @disabled={{this.saving}}
      @icon="far-square-check"
      @label={{if this.showLabel "solved.solution"}}
      @title="solved.accept_answer"
    />
  </template>
}

async function acceptPost(post) {
  if (!post.can_accept_answer || post.accepted_answer) {
    return;
  }

  const topic = post.topic;

  try {
    const acceptedAnswers = await ajax("/solution/accept", {
      type: "POST",
      data: { id: post.id },
    });

    setAcceptedSolutions(topic, acceptedAnswers);
  } catch (e) {
    popupAjaxError(e);
  }
}
import Component from "@glimmer/component";
import { service } from "@ember/service";
import userPrioritizedName from "discourse/helpers/user-prioritized-name";
import DInterpolatedTranslation from "discourse/ui-kit/d-interpolated-translation";
import DRelativeDate from "discourse/ui-kit/d-relative-date";
import DUserLink from "discourse/ui-kit/d-user-link";
import dBoundAvatarTemplate from "discourse/ui-kit/helpers/d-bound-avatar-template";
import { i18n } from "discourse-i18n";

export default class SolvedAccordionItemMetadata extends Component {
  @service siteSettings;

  get post() {
    return this.args.post;
  }

  get userDisplayName() {
    return userPrioritizedName({
      username: this.post.username,
      name: this.post.name,
    });
  }

  get accepterDisplayName() {
    return userPrioritizedName({
      username: this.post.accepter_username,
      name: this.post.accepter_name,
    });
  }

  get showAccepter() {
    return (
      !!this.siteSettings.show_who_marked_solved && this.post.accepter_username
    );
  }

  <template>
    <DUserLink class="user-link" @username={{this.post.username}}>
      {{dBoundAvatarTemplate this.post.avatar_template "tiny"}}
      <span>{{this.userDisplayName}}</span>
    </DUserLink>
    <span class="dot-separator"></span>
    <a class="date-link" href={{this.post.url}} title={{i18n "post.sr_date"}}>
      <DRelativeDate @date={{this.post.created_at}} />
    </a>

    {{#if this.showAccepter}}
      <span class="dot-separator"></span>

      <span class="accepter-name">
        <DInterpolatedTranslation
          @key="solved.marked_solved_by"
          as |Placeholder|
        >
          <Placeholder @name="user">

            <DUserLink
              class="accepter-link"
              @username={{this.post.accepter_username}}
            >
              {{this.accepterDisplayName}}
            </DUserLink>
          </Placeholder>
        </DInterpolatedTranslation>
      </span>
    {{/if}}
  </template>
}
import Component from "@glimmer/component";
import { service } from "@ember/service";
import DPostAccordion from "discourse/ui-kit/d-post-accordion";
import dIcon from "discourse/ui-kit/helpers/d-icon";
import { i18n } from "discourse-i18n";
import SolvedAccordionItemMetadata from "./solved-accordion-item-metadata.gjs";

const CHARS_PER_LINE = 90;

export default class SolvedAcceptedAnswers extends Component {
  static shouldRender(args) {
    return (
      args.post?.post_number === 1 &&
      args.post?.topic?.accepted_answers?.length > 0
    );
  }

  @service siteSettings;

  get topic() {
    return this.args.post.topic;
  }

  get acceptedAnswers() {
    return this.topic.accepted_answers ?? [];
  }

  get hasAnswer() {
    return !!this.acceptedAnswers;
  }

  get hasMultipleAnswers() {
    return this.acceptedAnswers?.length > 1;
  }

  get linesDisplayed() {
    const chars = this.siteSettings.solved_quote_length;
    if (chars <= 0) {
      return null;
    }

    return Math.max(1, Math.ceil(chars / CHARS_PER_LINE));
  }

  <template>
    <DPostAccordion
      class="accepted-answers"
      @decoratorState={{@decoratorState}}
      @linesDisplayed={{this.linesDisplayed}}
      @posts={{this.acceptedAnswers}}
    >
      <:header>
        <h3 class="accepted-answers__title">

          {{#if this.hasAnswer}}
            {{dIcon "far-square-check"}}
          {{/if}}

          {{i18n "solved.title"}}
        </h3>

        {{#if this.hasMultipleAnswers}}
          <span class="accepted-answers__solution-count">
            {{this.acceptedAnswers.length}}
            {{i18n "solved.solution_summary" count=this.acceptedAnswers.length}}
          </span>
        {{/if}}
      </:header>

      <:itemMetadata as |post|>
        <SolvedAccordionItemMetadata @post={{post}} />
      </:itemMetadata>
    </DPostAccordion>
  </template>
}
import Component from "@glimmer/component";
import { userPath } from "discourse/lib/url";
import { formatUsername } from "discourse/lib/utilities";
import dAvatar from "discourse/ui-kit/helpers/d-avatar";
import dCategoryBadge from "discourse/ui-kit/helpers/d-category-badge";
import { i18n } from "discourse-i18n";

export default class SolvedAdminReportRelatedItems extends Component {
  get solvedTopics() {
    return this.args.relatedItems?.solved_topics || [];
  }

  get solvedTopicsTotal() {
    return (
      this.args.relatedItemsTotals?.solved_topics || this.solvedTopics.length
    );
  }

  get solvedTopicsAreTruncated() {
    return this.solvedTopics.length < this.solvedTopicsTotal;
  }

  get startDate() {
    return moment(this.args.startDate).format(
      i18n("dates.long_with_year_no_time")
    );
  }

  get endDate() {
    return moment(this.args.endDate).format(
      i18n("dates.long_with_year_no_time")
    );
  }

  userProfilePath(user) {
    return userPath(user.username);
  }

  <template>
    {{#if this.solvedTopics.length}}
      <section
        class="admin-report-related-items solved-admin-report-related-items"
      >
        <h2>{{i18n "admin.reports.related_items.solved_topics.title"}}</h2>
        <p class="admin-report-related-items__description">
          {{i18n
            "admin.reports.related_items.solved_topics.description"
            startDate=this.startDate
            endDate=this.endDate
          }}
          {{#if this.solvedTopicsAreTruncated}}
            <span class="admin-report-related-items__limit">
              {{i18n
                "admin.reports.related_items.showing"
                shown=this.solvedTopics.length
                total=this.solvedTopicsTotal
              }}
            </span>
          {{/if}}
        </p>

        <table
          class="table admin-report-related-items__table solved-admin-report-related-items__table"
        >
          <thead>
            <tr>
              <th class="solved-admin-report-related-items__topic-cell">
                {{i18n "admin.reports.related_items.labels.topic"}}
              </th>
              <th class="solved-admin-report-related-items__solved-by-cell">
                {{i18n "admin.reports.related_items.labels.solved_by"}}
              </th>
              <th class="solved-admin-report-related-items__category-cell">
                {{i18n "admin.reports.related_items.labels.category"}}
              </th>
            </tr>
          </thead>
          <tbody>
            {{#each this.solvedTopics as |item|}}
              <tr>
                <td class="solved-admin-report-related-items__topic-cell">
                  <a
                    class="solved-admin-report-related-items__topic-link"
                    href={{item.topic.url}}
                  >
                    {{item.topic.title}}
                  </a>
                </td>
                <td class="solved-admin-report-related-items__solved-by-cell">
                  {{#let item.solved_by_users as |users|}}
                    {{#if users.length}}
                      <div
                        class="solved-admin-report-related-items__solved-by-users"
                      >
                        {{#each users as |user|}}
                          <a
                            class="admin-report-related-items__user-link"
                            href={{this.userProfilePath user}}
                          >
                            {{dAvatar
                              user
                              imageSize="small"
                              extraClasses="admin-report-related-items__avatar"
                            }}
                            <span class="admin-report-related-items__username">
                              {{formatUsername user.username}}
                            </span>
                          </a>
                        {{/each}}
                      </div>
                    {{/if}}
                  {{/let}}
                </td>
                <td class="solved-admin-report-related-items__category-cell">
                  {{#if item.category}}
                    {{dCategoryBadge item.category}}
                  {{else}}
                    {{i18n "category.none"}}
                  {{/if}}
                </td>
              </tr>
            {{/each}}
          </tbody>
        </table>
      </section>
    {{/if}}
  </template>
}
