import Component from "@glimmer/component";
import { tracked } from "@glimmer/tracking";
import { action } from "@ember/object";
import { service } from "@ember/service";
import { ajax } from "discourse/lib/ajax";
import { popupAjaxError } from "discourse/lib/ajax-error";
import DButton from "discourse/ui-kit/d-button";
import dConcatClass from "discourse/ui-kit/helpers/d-concat-class";
import { i18n } from "discourse-i18n";

export default class SolvedSharedIssueButton extends Component {
  @service currentUser;
  @service router;
  @service siteSettings;

  @tracked saving = false;

  get show() {
    const topic = this.args.post.topic;
    const hasAcceptedAnswers = topic.accepted_answers?.length > 0;

    return (
      topic.shared_issue_visible &&
      (!hasAcceptedAnswers || this.siteSettings.solved_allow_multiple_solutions)
    );
  }

  get count() {
    return this.args.post.topic.shared_issue_count ?? 0;
  }

  get hasSharedIssue() {
    return this.args.post.topic.user_created_shared_issue;
  }

  get isTopicAuthor() {
    return this.currentUser && this.currentUser.id === this.args.post.user_id;
  }

  get isClosed() {
    return this.args.post.topic.closed;
  }

  get isArchived() {
    return this.args.post.topic.archived;
  }

  get disabled() {
    return (
      this.saving || this.isTopicAuthor || this.isClosed || this.isArchived
    );
  }

  get titleKey() {
    if (this.isTopicAuthor) {
      return "solved.shared_issue.author_title";
    }
    if (this.isClosed) {
      return "solved.shared_issue.closed_title";
    }
    if (this.isArchived) {
      return "solved.shared_issue.archived_title";
    }
    return "solved.shared_issue.title";
  }

  get label() {
    const label = i18n("solved.shared_issue.label");
    if (this.count === 0) {
      return label;
    }
    return i18n("solved.shared_issue.label_with_count", {
      label,
      count: this.count,
    });
  }

  @action
  async toggle() {
    if (this.isTopicAuthor || this.isClosed || this.isArchived) {
      return;
    }

    if (!this.currentUser) {
      this.router.transitionTo("login");
      return;
    }

    const topic = this.args.post.topic;
    this.saving = true;

    try {
      const result = await ajax("/solution/shared_issue", {
        type: "POST",
        data: { topic_id: topic.id },
      });

      topic.set("shared_issue_count", result.count);
      topic.set("user_created_shared_issue", result.user_created_shared_issue);
    } catch (e) {
      popupAjaxError(e);
    } finally {
      this.saving = false;
    }
  }

  <template>
    {{#if this.show}}
      <div class="solved-shared-issue-row">
        <DButton
          class={{dConcatClass
            "btn-default"
            "post-action-menu__solved-shared-issue"
            (if this.hasSharedIssue "has-shared-issue")
            (if this.disabled "disabled")
          }}
          ...attributes
          @action={{this.toggle}}
          @disabled={{this.disabled}}
          @icon="hand"
          @title={{this.titleKey}}
          @translatedLabel={{this.label}}
        />
      </div>
    {{/if}}
  </template>
}
import Component from "@glimmer/component";
import { tracked } from "@glimmer/tracking";
import { action } from "@ember/object";
import { service } from "@ember/service";
import DTooltip from "discourse/float-kit/components/d-tooltip";
import { ajax } from "discourse/lib/ajax";
import { popupAjaxError } from "discourse/lib/ajax-error";
import DButton from "discourse/ui-kit/d-button";
import DInterpolatedTranslation from "discourse/ui-kit/d-interpolated-translation";
import DUserLink from "discourse/ui-kit/d-user-link";
import dIcon from "discourse/ui-kit/helpers/d-icon";
import { i18n } from "discourse-i18n";
import setAcceptedSolutions from "../lib/set-accepted-solutions.js";

export default class SolvedUnacceptAnswerButton extends Component {
  @service appEvents;
  @service siteSettings;

  @tracked saving = false;

  get answerInfo() {
    return this.args.post.topic.accepted_answers?.find(
      (a) => a.post_number === this.args.post.post_number
    );
  }

  get showAcceptedBy() {
    return !(
      !this.siteSettings.show_who_marked_solved ||
      !this.answerInfo?.accepter_username
    );
  }

  get acceptedByUsername() {
    return this.answerInfo?.accepter_username;
  }

  get acceptedByDisplayName() {
    const username = this.answerInfo?.accepter_username;
    const name = this.answerInfo?.accepter_name;
    return this.siteSettings.display_name_on_posts && name ? name : username;
  }

  @action
  async unacceptAnswer() {
    const post = this.args.post;

    this.saving = true;
    try {
      await unacceptPost(post);

      this.appEvents.trigger("discourse-solved:solution-toggled", post);
    } catch (e) {
      popupAjaxError(e);
    } finally {
      this.saving = false;
    }
  }

  <template>
    <span class="extra-buttons">
      {{#if (and @post.can_accept_answer @post.accepted_answer)}}
        {{#if this.showAcceptedBy}}
          <DTooltip @identifier="post-action-menu__solved-accepted-tooltip">
            <:trigger>
              <DButton
                class="post-action-menu__solved-accepted accepted fade-out"
                ...attributes
                @action={{this.unacceptAnswer}}
                @icon="square-check"
                @label="solved.solution"
                @title="solved.unaccept_answer"
              />
            </:trigger>
            <:content>
              <DInterpolatedTranslation
                @key="solved.marked_solved_by"
                as |Placeholder|
              >
                <Placeholder @name="user">
                  <DUserLink @username={{this.acceptedByUsername}}>
                    {{this.acceptedByDisplayName}}
                  </DUserLink>
                </Placeholder>
              </DInterpolatedTranslation>
            </:content>
          </DTooltip>
        {{else}}
          <DButton
            class="post-action-menu__solved-accepted accepted fade-out"
            ...attributes
            @action={{this.unacceptAnswer}}
            @disabled={{this.saving}}
            @icon="square-check"
            @label="solved.solution"
            @title="solved.unaccept_answer"
          />
        {{/if}}
      {{else}}
        <span
          class="accepted-text"
          title={{i18n "solved.accepted_description"}}
        >
          <span>{{dIcon "check"}}</span>
          <span class="accepted-label">
            {{i18n "solved.solution"}}
          </span>
        </span>
      {{/if}}
    </span>
  </template>
}

async function unacceptPost(post) {
  if (!post.can_accept_answer || !post.accepted_answer) {
    return;
  }

  const topic = post.topic;

  try {
    const remainingAcceptedAnswers = await ajax("/solution/unaccept", {
      type: "POST",
      data: { id: post.id },
    });

    setAcceptedSolutions(topic, remainingAcceptedAnswers);
  } catch (e) {
    popupAjaxError(e);
  }
}
import dIcon from "discourse/ui-kit/helpers/d-icon";
import { i18n } from "discourse-i18n";

const SolvedStatus = <template>
  {{~#if
    (or @outletArgs.topic.has_accepted_answer @outletArgs.topic.accepted_answer)
  ~}}
    <span
      class="topic-status --solved"
      title={{i18n "topic_statuses.solved.help"}}
    >{{dIcon "far-square-check"}}</span>
  {{~else if
    (and
      @outletArgs.topic.can_have_answer (eq @outletArgs.context "topic-list")
    )
  ~}}
    <span
      class="topic-status --unsolved"
      title={{i18n "solved.has_no_accepted_answer"}}
    >{{dIcon "far-square"}}</span>
  {{~/if~}}
</template>;

export default SolvedStatus;
import Component from "@glimmer/component";
import { hash } from "@ember/helper";
import { action } from "@ember/object";
import { service } from "@ember/service";
import ComboBox from "discourse/select-kit/components/combo-box";
import { i18n } from "discourse-i18n";

const QUERY_PARAM_VALUES = {
  solved: "yes",
  unsolved: "no",
  all: null,
};

const UX_VALUES = {
  yes: "solved",
  no: "unsolved",
};

export default class SolvedStatusFilter extends Component {
  static shouldRender(args, context, owner) {
    const router = owner.lookup("service:router");

    if (
      !context.siteSettings.show_filter_by_solved_status ||
      router.currentRouteName === "discovery.categories" ||
      args.editingCategory
    ) {
      return false;
    } else if (
      context.siteSettings.allow_solved_on_all_topics ||
      router.currentRouteName === "tag.show"
    ) {
      return true;
    } else {
      return (
